package app.scalemate.health

import org.json.JSONArray
import org.json.JSONObject

object HealthJson {
    private fun strings(values:Collection<String>)=JSONArray(values.toList())
    fun strings(array:JSONArray?)=(0 until (array?.length() ?: 0)).map {array!!.getString(it)}
    private fun objects(array:JSONArray?)=(0 until (array?.length() ?: 0)).map {array!!.getJSONObject(it)}
    fun window(w:HealthWindow)=JSONObject().put("start",w.start).put("end",w.end).put("zone",w.zone).put("allHistory",w.allHistory)
    fun window(o:JSONObject)=HealthWindow(o.getString("start"),o.getString("end"),o.getString("zone"),o.optBoolean("allHistory"))
    fun evidence(e:HealthEvidence)=JSONObject().put("id",e.id).put("kind",e.kind).put("date",e.date).put("source",e.source).put("field",e.field).put("value",e.value).put("unit",e.unit).put("count",e.count).put("coverage",e.coverage ?: JSONObject.NULL).put("partial",e.partial).put("algorithm",e.algorithm).put("detail",if(e.detail.isEmpty())JSONObject.NULL else JSONObject(e.detail))
    fun evidence(o:JSONObject)=HealthEvidence(o.getString("id"),o.getString("kind"),o.getString("date"),o.getString("source"),o.getString("field"),o.getDouble("value"),o.getString("unit"),o.getInt("count"),if(o.isNull("coverage"))null else o.getDouble("coverage"),o.optBoolean("partial"),o.getString("algorithm"),if(o.isNull("detail"))"" else o.getJSONObject("detail").toString())
    fun snapshot(s:HealthSnapshot)=JSONObject().put("id",s.id).put("readAt",s.readAt).put("window",window(s.window)).put("categories",strings(s.categories.sorted())).put("evidence",JSONArray(s.evidence.map(::evidence))).put("coverage",JSONArray(s.coverage.map {JSONObject().put("kind",it.kind).put("status",it.status).put("records",it.records).put("points",it.points).put("sources",strings(it.sources)).put("latest",it.latest ?: JSONObject.NULL)})).put("warnings",strings(s.warnings)).put("rawFile",s.rawFile).put("baselineStart",s.baselineStart).put("syncTokens",JSONObject(s.syncTokens))
    fun snapshot(o:JSONObject)=HealthSnapshot(o.getString("id"),o.getLong("readAt"),window(o.getJSONObject("window")),strings(o.getJSONArray("categories")).toSet(),objects(o.getJSONArray("evidence")).map(::evidence),objects(o.getJSONArray("coverage")).map {HealthCoverage(it.getString("kind"),it.getString("status"),it.getLong("records"),it.getLong("points"),strings(it.optJSONArray("sources")),if(it.isNull("latest"))null else it.getLong("latest"))},strings(o.optJSONArray("warnings")),o.optString("rawFile"),o.getString("baselineStart"),o.optJSONObject("syncTokens")?.let {tokens->tokens.keys().asSequence().associateWith(tokens::getString)}.orEmpty())
    fun message(m:HealthMessage)=JSONObject().put("id",m.id).put("role",m.role).put("text",m.text).put("createdAt",m.createdAt).put("snapshotId",m.snapshotId).put("serviceId",m.serviceId).put("serviceName",m.serviceName).put("model",m.model).put("configVersion",m.configVersion).put("status",m.status).put("evidenceIds",strings(m.evidenceIds))
    fun message(o:JSONObject)=HealthMessage(o.getString("id"),o.getString("role"),o.getString("text"),o.getLong("createdAt"),o.optString("snapshotId"),o.optString("serviceId"),o.optString("serviceName"),o.optString("model"),o.optLong("configVersion"),o.optString("status","complete"),strings(o.optJSONArray("evidenceIds")))
    fun conversation(c:HealthConversation)=JSONObject().put("id",c.id).put("title",c.title).put("messages",JSONArray(c.messages.map(::message)))
    fun conversation(o:JSONObject)=HealthConversation(o.getString("id"),o.getString("title"),objects(o.optJSONArray("messages")).map(::message))
    fun reminders(s:HealthReminderSettings)=JSONObject().put("enabled",s.enabled).put("sleep",s.sleep).put("recovery",s.recovery).put("activity",s.activity).put("bedtime",s.bedtime).put("checkMinute",s.checkMinute).put("quietStart",s.quietStart).put("quietEnd",s.quietEnd).put("bedtimeMinute",s.bedtimeMinute).put("showDetails",s.showDetails)
    fun reminders(o:JSONObject)=HealthReminderSettings(o.optBoolean("enabled"),o.optBoolean("sleep",true),o.optBoolean("recovery"),o.optBoolean("activity",true),o.optBoolean("bedtime"),o.optInt("checkMinute",630),o.optInt("quietStart",1320),o.optInt("quietEnd",540),o.optInt("bedtimeMinute",1260),o.optBoolean("showDetails"))
    fun reminder(r:HealthReminder)=JSONObject().put("id",r.id).put("topics",strings(r.topics)).put("evidenceIds",strings(r.evidenceIds)).put("createdAt",r.createdAt).put("snapshotId",r.snapshotId).put("key",r.key).put("feedback",r.feedback)
    fun reminder(o:JSONObject)=HealthReminder(o.getString("id"),strings(o.getJSONArray("topics")),strings(o.getJSONArray("evidenceIds")),o.getLong("createdAt"),o.getString("snapshotId"),o.getString("key"),o.optString("feedback"))
    fun record(r:HealthRecord)=JSONObject().put("recordId",r.id).put("category",r.kind).put("source",r.source).put("start",if(r.kind.startsWith("Medical_")&&r.start==0L)JSONObject.NULL else java.time.Instant.ofEpochMilli(r.start)).put("end",if(r.kind.startsWith("Medical_")&&r.start==0L)JSONObject.NULL else java.time.Instant.ofEpochMilli(r.end)).put("zoneOffsetSeconds",r.offsetSeconds ?: JSONObject.NULL).put("values",JSONObject().apply {r.values.forEach {(k,v)->put(k,JSONObject().put("value",v.value).put("unit",v.unit))}}).put("samples",JSONArray(r.points.map {JSONObject().put("time",java.time.Instant.ofEpochMilli(it.time)).put("value",it.value).put("unit",it.unit)})).put("stages",JSONArray(r.stages.map {JSONObject().put("start",java.time.Instant.ofEpochMilli(it.start)).put("end",java.time.Instant.ofEpochMilli(it.end)).put("stage",it.stage)})).apply {if(r.detail.isNotEmpty())put("detail",JSONObject(r.detail))}
    fun cacheRecord(r:HealthRecord)=record(r).put("platformId",r.platformId)
    fun cachedRecord(o:JSONObject)=record(o).copy(platformId=o.optString("platformId"))
    fun record(o:JSONObject):HealthRecord {
        fun at(value:String)=if(value=="null")0L else java.time.Instant.parse(value).toEpochMilli()
        val values=o.getJSONObject("values")
        return HealthRecord(o.getString("recordId"),o.getString("category"),o.getString("source"),if(o.isNull("start"))0L else at(o.getString("start")),if(o.isNull("end"))0L else at(o.getString("end")),values.keys().asSequence().associateWith {key->val v=values.getJSONObject(key);HealthValue(v.getDouble("value"),v.getString("unit"))},objects(o.optJSONArray("samples")).map {HealthPoint(at(it.getString("time")),it.getDouble("value"),it.getString("unit"))},objects(o.optJSONArray("stages")).map {HealthStage(at(it.getString("start")),at(it.getString("end")),it.getInt("stage"))},o.optJSONObject("detail")?.toString().orEmpty(),if(o.isNull("zoneOffsetSeconds"))null else o.getInt("zoneOffsetSeconds"),o.optString("platformId"))
    }
}
